`,e.jsx("span",{id:"architecture-changes"}),`
`,e.jsx(t.h2,{id:"changes",children:"Changes"}),`
`,e.jsxs(t.p,{children:["These changes alter how Lamassu is deployed, where it stores its data and how that data is converted. They do not change the API or the events: what clients, integrations and devices have to adapt to is listed under ",e.jsx(t.a,{href:"#breaking-changes",children:"Breaking changes"}),". Most of these changes are applied by the upgrade itself; the ones that need operator action say so, and the ",e.jsx(t.a,{href:"#helm-migration-guide",children:"Helm migration guide"})," performs that action in order."]}),`
`,e.jsx(t.h3,{id:"what-the-upgrade-migrates-automatically",children:"What the upgrade migrates automatically"}),`
`,e.jsx(t.p,{children:"Several migrations run without intervention when you upgrade a Helm release:"}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["Before any service starts, the chart's pre-install/pre-upgrade job prepares PostgreSQL. It creates the ",e.jsx(t.code,{children:"pki"}),", ",e.jsx(t.code,{children:"authz"})," and ",e.jsx(t.code,{children:"wfx"})," databases when they do not exist, creates one schema per service inside ",e.jsx(t.code,{children:"pki"}),", and imports each 3.8.0 per-service database into its schema. Each import runs as a single transaction, so a failed import leaves no partial schema and a retried job imports again. The job then runs the database migrations for every schema, migrates ",e.jsx(t.code,{children:"authz"}),", preloads its policies and seeds the ",e.jsx(t.code,{children:"services.authz.bootstrap"})," principals. It is idempotent and requires a PostgreSQL role allowed to create databases and schemas, as described in ",e.jsx(t.a,{href:"/docs/deployment/self-hosted/helm#before-you-begin",children:"Install with Helm"}),"."]}),`
`,e.jsx(t.li,{children:"Stored DMS configuration is rewritten to the 4.0.0 layout, and historical device events are transformed into the new store."}),`
`,e.jsxs(t.li,{children:["The KMS migration removes the stale ",e.jsx(t.code,{children:"lamassu.io/kms/binded-resources"})," key metadata and the aliases that equal an existing key ID (see ",e.jsx(t.a,{href:"#conflicting-kms-key-aliases",children:"Conflicting KMS key aliases"}),"). The VA migration turns each VA role into the CRL settings of its CA and resolves its CRL signer (see ",e.jsx(t.a,{href:"#crl-settings-migration",children:"CRL settings migration"}),")."]}),`
`,e.jsxs(t.li,{children:["When ",e.jsx(t.code,{children:"migrations.caToKms.enabled"})," is set, a pre-upgrade hook registers legacy CA keys in the KMS."]}),`
`]}),`
`,e.jsxs(t.p,{children:["Two things never migrate on their own: the KMS and VA data on local volumes, which stays on volumes the upgraded pods no longer use, and the values file, which you update by hand. Deployments that do not use the Helm chart also have to move their database data themselves; see ",e.jsx(t.a,{href:"#deployments-without-helm",children:"Deployments without Helm"}),"."]}),`
`,e.jsx(t.h3,{id:"helm-chart-and-deployment",children:"Helm chart and deployment"}),`
`,e.jsx(t.h4,{id:"a-hardened-helm-chart",children:"A hardened Helm chart"}),`
`,e.jsx(t.p,{children:"Version 4.0.0 of the chart is a security-hardening release:"}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Release-scoped resource names."})," Every chart-managed resource is named ",e.jsx(t.code,{children:"<release>-lamassu-<component>"})," instead of the fixed names used in 3.8.0 (",e.jsx(t.code,{children:"kms"}),", ",e.jsx(t.code,{children:"va"}),", ",e.jsx(t.code,{children:"ca"}),", ...). With a release named ",e.jsx(t.code,{children:"prod"})," the StatefulSets become ",e.jsx(t.code,{children:"prod-lamassu-kms"})," and ",e.jsx(t.code,{children:"prod-lamassu-va"}),". The ",e.jsx(t.code,{children:"nameOverride"})," and ",e.jsx(t.code,{children:"fullnameOverride"})," values change the prefix."]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Non-root containers."})," Every workload runs as the numeric user ",e.jsx(t.code,{children:"65532:65532"})," and existing volumes must be accessible to that identity."]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"Strict values validation."})," ",e.jsx(t.code,{children:"values.schema.json"})," rejects unknown keys, so leftover 3.8.0 blocks fail ",e.jsx(t.code,{children:"helm lint"})," and ",e.jsx(t.code,{children:"helm upgrade"})," instead of being silently ignored."]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.strong,{children:"No injected scheduling rules."})," The chart no longer adds pod anti-affinity or topology spread constraints on its own."]}),`
`]}),`
`,e.jsx(t.h4,{id:"release-scoped-resource-names",children:"Release-scoped resource names"}),`
`,e.jsxs(t.p,{children:["Kubernetes derives a StatefulSet's PVC name from its pod name (",e.jsx(t.code,{children:"<volumeClaimTemplate>-<pod-name>"}),"). Renaming the ",e.jsx(t.code,{children:"kms"})," and ",e.jsx(t.code,{children:"va"})," StatefulSets means ",e.jsx(t.code,{children:"helm upgrade"})," binds brand-new, empty PVCs instead of the existing ones. The KMS key material and VA CRLs are not deleted — the old PVCs are orphaned, not removed — but the upgraded pods fail with ",e.jsx(t.code,{children:"no such file or directory"})," (KMS) or ",e.jsx(t.code,{children:"code=NotFound"})," (VA) until you copy the data across. This affects KMS when ",e.jsx(t.code,{children:"services.kms.cryptoEngines"})," uses a ",e.jsx(t.code,{children:"filesystem"})," engine and VA when ",e.jsx(t.code,{children:"services.va.fileStore.type"})," is ",e.jsx(t.code,{children:"local"}),". Every other renamed resource is stateless and is recreated without data-loss risk."]}),`
`,e.jsxs(t.p,{children:[e.jsx(t.a,{href:"#step-4-migrate-the-kms-and-va-data",children:"Step 4 of the migration guide"})," copies the data."]}),`
`,e.jsx(t.h4,{id:"non-root-containers",children:"Non-root containers"}),`
`,e.jsxs(t.p,{children:["Service images run on a distroless base as the numeric user ",e.jsx(t.code,{children:"65532"}),"; the ",e.jsx(t.code,{children:"authz"})," image is Ubuntu with a non-root user that has the same UID. The per-service overrides ",e.jsx(t.code,{children:"services.kms.securityContext.runAsGroup: 0"})," and ",e.jsx(t.code,{children:"services.authz.securityContext.runAsUser"}),"/",e.jsx(t.code,{children:"runAsGroup: 999"})," are removed; group access to the KMS volume and PKCS#11 socket is now handled by the pod-level ",e.jsx(t.code,{children:"fsGroup: 65532"}),"."]}),`
`,e.jsxs(t.p,{children:["3.8.0 did not pin a container identity, so existing files can carry any UID. Any volume that holds keys or CRLs must be owned by ",e.jsx(t.code,{children:"65532:65532"}),", or at least readable (and, where needed, writable) by that identity."]}),`
`,e.jsxs(t.p,{children:["Pods now carry a pod-level ",e.jsx(t.code,{children:"fsGroup: 65532"})," with ",e.jsx(t.code,{children:"fsGroupChangePolicy: OnRootMismatch"}),", which skips recursive ownership changes when the volume root already has the expected group. If your backup helpers or jobs run with a different GID, verify they can still access the volumes they need."]}),`
`,e.jsx(t.h4,{id:"strict-values-validation",children:"Strict values validation"}),`
`,e.jsxs(t.p,{children:[e.jsx(t.code,{children:"values.schema.json"})," rejects unknown keys, so every block that 4.0.0 removed or renamed — ",e.jsx(t.code,{children:"toolbox"}),", ",e.jsx(t.code,{children:"auth.oidc.apiGateway"}),", ",e.jsx(t.code,{children:"auth.authorization"})," and others — fails ",e.jsx(t.code,{children:"helm lint"})," and ",e.jsx(t.code,{children:"helm upgrade"})," outright. ",e.jsx(t.a,{href:"#step-2-update-the-values-file",children:"Step 2"})," lists every change."]}),`
`,e.jsx(t.h4,{id:"credentials-in-kubernetes-secrets",children:"Credentials in Kubernetes Secrets"}),`
`,e.jsxs(t.p,{children:["In 4.0.0 the chart reads PostgreSQL, AMQP and SMTP credentials from Kubernetes Secrets in the release namespace instead of inline values: ",e.jsx(t.code,{children:"postgres.existingSecret"}),", ",e.jsx(t.code,{children:"amqp.existingSecret"})," and — when SMTP authentication is configured — ",e.jsx(t.code,{children:"services.alerts.smtp_server.existingSecret"}),", each with ",e.jsx(t.code,{children:"usernameKey"})," and ",e.jsx(t.code,{children:"passwordKey"})," naming the Secret data keys. The inline ",e.jsx(t.code,{children:"postgres.username"}),"/",e.jsx(t.code,{children:"postgres.password"})," and ",e.jsx(t.code,{children:"amqp.username"}),"/",e.jsx(t.code,{children:"amqp.password"})," values are removed and rejected by ",e.jsx(t.code,{children:"values.schema.json"}),", so a 3.8.0 values file fails ",e.jsx(t.code,{children:"helm lint"})," and ",e.jsx(t.code,{children:"helm upgrade"})," until the credentials move into Secrets."]}),`
`,e.jsxs(t.p,{children:["The Secrets must exist before ",e.jsx(t.code,{children:"helm upgrade"})," runs: the pre-upgrade database job connects to PostgreSQL with them. ",e.jsx(t.a,{href:"#step-2-update-the-values-file",children:"Step 2"})," creates them through the External Secrets Operator."]}),`
`,e.jsx(t.h4,{id:"renamed-and-reshaped-values",children:"Renamed and reshaped values"}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:[e.jsx(t.code,{children:"toolbox"})," is renamed to ",e.jsx(t.code,{children:"connectivityTest"}),", and the ",e.jsx(t.code,{children:"helm test"})," hook uses the upstream ",e.jsx(t.code,{children:"curlimages/curl"})," image pinned by digest."]}),`
`,e.jsxs(t.li,{children:[e.jsx(t.code,{children:"services.connectors"})," is a map keyed by connector ID instead of a list."]}),`
`,e.jsxs(t.li,{children:["The ",e.jsx(t.code,{children:"services.ui.port"})," default is ",e.jsx(t.code,{children:"8085"}),", the unprivileged port of the rootless image."]}),`
`,e.jsxs(t.li,{children:["The shared ",e.jsx(t.code,{children:"probes:"})," block is replaced by independent ",e.jsx(t.code,{children:"livenessProbe"}),", ",e.jsx(t.code,{children:"readinessProbe"})," and ",e.jsx(t.code,{children:"startupProbe"})," blocks."]}),`
`,e.jsxs(t.li,{children:["With ",e.jsx(t.code,{children:"tls.certManagerOptions.issuer"})," empty, the chart creates a release-scoped self-signed issuer, for example ",e.jsx(t.code,{children:"lamassu-downstream-ca-selfsigned-issuer"}),". The legacy literal ",e.jsx(t.code,{children:"downstream-ca-selfsigned-issuer"})," is still accepted and resolves to it."]}),`
`,e.jsxs(t.li,{children:["Anti-affinity and topology spread must be configured explicitly through ",e.jsx(t.code,{children:"affinity"})," and ",e.jsx(t.code,{children:"topologySpreadConstraints"}),"."]}),`
`]}),`
`,e.jsx(t.h4,{id:"amqp-over-tls",children:"AMQP over TLS"}),`
`,e.jsxs(t.p,{children:["In 3.8.0 ",e.jsx(t.code,{children:"amqp.tls"})," was not applied and event-bus clients always connected over plaintext. In 4.0.0 ",e.jsx(t.code,{children:"amqp.tls: true"})," switches them to AMQPS. The default ",e.jsx(t.code,{children:"amqp.port"})," stays ",e.jsx(t.code,{children:"5672"})," and does not change when TLS is enabled, so a values file that already set ",e.jsx(t.code,{children:"amqp.tls: true"})," must point ",e.jsx(t.code,{children:"amqp.port"})," at the broker's TLS listener (",e.jsx(t.code,{children:"amqps"}),", commonly ",e.jsx(t.code,{children:"5671"}),"), or set ",e.jsx(t.code,{children:"amqp.tls: false"})," to keep plaintext. Clients must also trust the broker's certificate."]}),`
`,e.jsx(t.h3,{id:"authorization",children:"Authorization"}),`
`,e.jsx(t.h4,{id:"authorization-moves-into-the-authz-service",children:"Authorization moves into the authz service"}),`
`,e.jsx(t.p,{children:"In 3.8.0 the API Gateway validated tokens: a JWT policy on every private route checked the signature and only let through tokens that carried the administrator role. Every route was open to any token that passed that check."}),`
`,e.jsxs(t.p,{children:["4.0.0 removes the gateway policy. The ",e.jsx(t.code,{children:"/api/*"})," routes reach the services directly, and each service authorizes every request through ",e.jsx(t.code,{children:"authz"}),", which validates the token against the identity provider's JWKS endpoint and applies fine-grained, entity-level policies to CAs, certificates, devices, DMSs, KMS keys and CRL settings. There is no implicit superuser: the first administrator comes from a bootstrap principal that you configure. The ",e.jsx(t.a,{href:"/docs/platform/administration/access-control",children:"access control"})," page documents principals, policies and the first administrator."]}),`
`,e.jsx(t.h4,{id:"required-authorization-configuration",children:"Required authorization configuration"}),`
`,e.jsxs(t.p,{children:["3.8.0 had no authorization service, so a 3.8.0 values file has nothing to migrate from: you must add the ",e.jsx(t.code,{children:"services.authz"})," configuration yourself. It needs the JWKS endpoint of your identity provider, the database mappings the authorization engine uses, and a bootstrap principal that matches how your provider assigns the administrator role. Without a matching principal nobody can administer the PKI."]}),`
`,e.jsx(t.h4,{id:"gateway-token-validation-removed",children:"Gateway token validation removed"}),`
`,e.jsxs(t.p,{children:[e.jsx(t.code,{children:"auth.oidc.apiGateway.jwks"}),", ",e.jsx(t.code,{children:"auth.authorization.rolesClaim"})," and ",e.jsx(t.code,{children:"auth.authorization.roles.admin"})," are removed with no compatibility aliases, and the schema rejects them. Their settings move into ",e.jsx(t.code,{children:"services.authz"}),": the JWKS URL becomes ",e.jsx(t.code,{children:"services.authz.jwkUrl"}),", and the role claim and administrator role become a claim rule of the bootstrap principal. ",e.jsx(t.code,{children:"auth.oidc.frontend"})," is unchanged."]}),`
`,e.jsx(t.h3,{id:"storage-and-data",children:"Storage and data"}),`
`,e.jsx(t.h4,{id:"one-postgresql-database-with-schemas",children:"One PostgreSQL database with schemas"}),`
`,e.jsxs(t.p,{children:["3.8.0 gave each service its own database. The 4.0.0 backend connects to a single PostgreSQL database named ",e.jsx(t.code,{children:"pki"})," and isolates each service in a schema: ",e.jsx(t.code,{children:"kms"}),", ",e.jsx(t.code,{children:"ca"}),", ",e.jsx(t.code,{children:"va"}),", ",e.jsx(t.code,{children:"devicemanager"}),", ",e.jsx(t.code,{children:"dmsmanager"})," and ",e.jsx(t.code,{children:"alerts"}),". The ",e.jsx(t.code,{children:"authz"})," service keeps its principals, grants and policies in a separate ",e.jsx(t.code,{children:"authz"})," database (the development monolith uses an ",e.jsx(t.code,{children:"authz"})," schema inside ",e.jsx(t.code,{children:"pki"})," instead), and WFX keeps its own ",e.jsx(t.code,{children:"wfx"})," database."]}),`
`,e.jsx("span",{id:"sqlite-storage-removed"}),`
`,e.jsxs(t.p,{children:["PostgreSQL is now the only storage engine. The SQLite storage engine is removed, and the ",e.jsx(t.code,{children:"couch_db"})," and ",e.jsx(t.code,{children:"dynamo_db"})," engines are not registered in 4.0.0: their configuration constants remain, but they select no engine. Deployments on any of them must move to PostgreSQL and consolidate their data into the ",e.jsx(t.code,{children:"pki"})," schemas before upgrading."]}),`
`,e.jsx(t.h4,{id:"postgresql-consolidation",children:"PostgreSQL consolidation"}),`
`,e.jsxs(t.p,{children:["Every 3.8.0 per-service database must end up as a schema of ",e.jsx(t.code,{children:"pki"}),", keeping its structure, indexes, constraints, data and migration history. The Helm chart does this automatically; deployments without Helm do it by hand (see ",e.jsx(t.a,{href:"#deployments-without-helm",children:"Deployments without Helm"}),")."]}),`
`,e.jsx(t.p,{children:"Two schema migrations abort on data that 3.8.0 allowed, so clean the data before upgrading:"}),`
`,e.jsxs(t.ul,{children:[`
`,e.jsxs(t.li,{children:["The CA migration adds a UNIQUE constraint on ",e.jsx(t.code,{children:"ca_certificates.id"})," and aborts if duplicate CA IDs exist. Imports already reject duplicates with ",e.jsx(t.code,{children:"409"}),", so new ones cannot normally appear."]}),`
`,e.jsxs(t.li,{children:["The KMS migration promotes the primary key to ",e.jsx(t.code,{children:"(key_id, engine_id)"})," and aborts with ",e.jsx(t.code,{children:"cannot promote (key_id, engine_id) to primary key: N row(s) have no engine_id; backfill them before migrating"})," when ",e.jsx(t.code,{children:"kms_keys"})," rows lack ",e.jsx(t.code,{children:"engine_id"}),". Backfill ",e.jsx(t.code,{children:"engine_id"})," first."]}),`
